INSERT OR IGNORE INTO failure_modes (fm_key, failure_mode, root_cause, remediation, detector, probe_class, first_seen, issue_id, trigger_condition, symptom, blast_radius) VALUES
 ('outward-prose-unjudged-final-text', 'pieces publish that no quality check ever read in their final form', 'the reader panel judged the draft before the fact check; the prune and revision rounds then cut it to a stub that went straight to publication', 'q08-signal-engine 0.21.0 Q08-FINAL-READ-1: the exact text that would be published needs 2800 characters of body and a final two-family reader panel with a vacuity-focused prompt (mean 4, no judge under 3), failing closed', 'no q08 piece published after 2026-10-13T18:20Z has a body under 2800 characters', 'fm-outward-prose-unjudged-final-text', '2026-10-13', NULL, 'any repair step (prune, revision, editor) that runs after the last quality judgement', 'published essays of 1272-2156 characters whose analysis is abstract nouns', 'every reader of q08.org'),
 ('outward-prose-source-starved', 'the writer has almost nothing to analyse, so it pads with abstraction or invents detail the fact-check then cuts', 'the five longest Hacker News comments were joined and cut to 800 characters, arXiv abstracts to 800, and the fact-checkers rejected background reference facts as not source', 'q08-signal-engine 0.21.0 Q08-SOURCE-DEPTH-1: eight comments one per line and abstracts up to 3000 characters; both fact-check prompts state that background and comments count as source', 'no Hacker News signal logged after 2026-10-13T18:20Z was cut at exactly 800 characters', 'fm-outward-prose-source-starved', '2026-10-13', NULL, 'a fixed small slice of the source handed to the writer', 'quotes neither side could see; background facts flagged as unsupported (run 384)', 'q08.org essays'),
 ('writer-reasoning-models-excluded', 'the strongest available writer models were kept out of the writer list', 'compose() never passed the per-model reasoning switch, so reasoning models spent the token budget thinking and returned empty content; they were removed instead of configured', 'q08-signal-engine 0.22.0 Q08-WRITER-UPGRADE-1: compose() passes factCheckExtra, 8000 output tokens, kimi-k2.6 first with nemotron and gpt-oss as per-request fallback', 'no q08 run after 2026-10-13T19:00Z fails with all compose models failed', 'fm-writer-reasoning-models-excluded', '2026-10-13', 2478, 'a model integration that drops a model rather than fixing its call parameters', 'two mid-tier writers produce generic prose that readers reject', 'q08.org'),
 ('q08-analysis-marker-rejected', 'the writer marks its analysis section where the guard rails refuse it, so its reasoning is checked line by line and pruned away', 'the split took the marker only where the writer placed it; a marker with under 600 characters of reporting before it sent the whole essay to the strict check (run 381)', 'q08-signal-engine 0.20.1 Q08-MARK-SHIFT-1: a refused marker moves later, paragraph by paragraph, to the first place the guard rails accept', 'no q08 run after 2026-10-13T16:20Z ends with analysis section: marked-rejected', 'fm-q08-analysis-marker-rejected', '2026-10-13', NULL, 'a deterministic split that rejects instead of repairing', 'the reasoning listed as unsupported and the draft pruned to under 1000 characters', 'q08.org'),
 ('q08-verdict-line-missing', 'runs fail only because the writer omitted or misformatted its final verdict line', 'a near-miss line (bold, colon) failed the exact pattern, and a draft missing only that line was sent to a full rewrite before the cheap verdict call', 'q08-signal-engine 0.20.2 Q08-VERDICT-NORM-1: near-miss lines normalised keeping the writer''s word; the verdict call runs first and reads the essay', 'no q08 run after 2026-10-13T17:15Z fails with only the verdict-line problem', 'fm-q08-verdict-line-missing', '2026-10-13', NULL, 'a format marker checked by exact regex', '12 failed runs in 7 days with error missing or malformed worth your time verdict line', 'q08.org');
